function(container, apiUrl, tables) {
  let storeData = [];
  let productData = [];
  let forecastData = [];
  let calculationResults = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    const errorText = container.querySelector("#error-text");
    errorText.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // 成功時のセクション表示
  function showResultSections() {
    container.querySelector("#forecast-display").classList.remove("hidden");
    container.querySelector("#inventory-display").classList.remove("hidden");
    container.querySelector("#results-section").classList.remove("hidden");
  }

  // 店舗データの読み込み
  async function loadStoreData() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores;
        const storeSelect = container.querySelector("#store-select");
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
        stores.forEach(store => {
          if (store.有効フラグ) {
            storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
          }
        });
      }
    } catch (error) {
      console.error('店舗データの読み込みに失敗しました:', error);
    }
  }

  // 商品データの読み込み
  async function loadProductData() {
    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);
      }
    } catch (error) {
      console.error('商品データの読み込みに失敗しました:', error);
    }
  }

  // 需要予測データの読み込み
  async function loadForecastData() {
    try {
      const forecasts = await window.aivicApi.list(9); // 需要予測結果
      if (forecasts) {
        forecastData = forecasts;
      }
    } catch (error) {
      showError('需要予測データの取得に失敗しました');
      return false;
    }
    return true;
  }

  // 在庫データの取得（売上実績データから推定）
  async function getInventoryData(storeId, productId) {
    try {
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData) {
        showError('在庫データの取得に失敗しました');
        return null;
      }

      // 最新の売上データから在庫を推定（簡易実装）
      const recentSales = salesData
        .filter(s => s.店舗ID === storeId && s.商品ID === productId)
        .sort((a, b) => new Date(b.売上日) - new Date(a.売上日))
        .slice(0, 30); // 直近30日

      const avgDailySales = recentSales.length > 0 
        ? Math.round(recentSales.reduce((sum, s) => sum + s.販売数量, 0) / recentSales.length)
        : 0;

      // 仮想的な現在在庫数（実際のシステムでは在庫マスタから取得）
      const currentStock = Math.max(0, Math.floor(Math.random() * 500) + avgDailySales * 3);

      return {
        currentStock,
        avgDailySales
      };
    } catch (error) {
      showError('在庫データの取得に失敗しました');
      return null;
    }
  }

  // 発注量計算ロジック
  function calculateOrderQuantity(forecast, inventory, safetyStock, leadTime, reorderPoint) {
    const predictedDemand = forecast.予測数量 || 0;
    const currentStock = inventory.currentStock || 0;
    const avgDailySales = inventory.avgDailySales || 0;

    // リードタイム中の予想消費量
    const leadTimeDemand = avgDailySales * leadTime;

    // 発注点の計算（入力値がない場合は自動計算）
    const calculatedReorderPoint = reorderPoint > 0 ? reorderPoint : leadTimeDemand + safetyStock;

    // 発注量の計算
    let orderQuantity = 0;
    let orderTiming = "発注不要";

    if (currentStock <= calculatedReorderPoint) {
      // 最大在庫量 = 安全在庫 + リードタイム需要 + 予測需要
      const maxStock = safetyStock + leadTimeDemand + predictedDemand;
      orderQuantity = Math.max(0, maxStock - currentStock);
      orderTiming = "即時発注";
    } else {
      // 在庫が十分な場合の予測
      const daysUntilReorder = Math.floor((currentStock - calculatedReorderPoint) / Math.max(avgDailySales, 1));
      if (daysUntilReorder <= 7) {
        orderTiming = `${daysUntilReorder}日後`;
      }
    }

    return {
      orderQuantity,
      orderTiming,
      reorderPoint: calculatedReorderPoint
    };
  }

  // 計算結果の表示
  function renderResults(results) {
    const tbody = container.querySelector("#results-tbody");
    tbody.innerHTML = results.map(result => `
      <tr data-id="${result.id}">
        <td><a href="#" class="product-detail-link" data-product-id="${result.productId}" style="color: var(--primary); text-decoration: none;">${result.productName}</a></td>
        <td>${result.productCode}</td>
        <td>${result.predictedDemand}</td>
        <td>${result.currentStock}</td>
        <td>${result.safetyStock}</td>
        <td>${result.reorderPoint}</td>
        <td>${result.orderQuantity}</td>
        <td>${result.orderTiming}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-product-id="${result.productId}">詳細</button>
        </td>
      </tr>
    `).join("");

    // 需要予測結果表示の更新
    const forecastContent = container.querySelector("#forecast-content");
    const totalPredicted = results.reduce((sum, r) => sum + r.predictedDemand, 0);
    forecastContent.innerHTML = `
      <p><strong>予測対象商品数:</strong> ${results.length}件</p>
      <p><strong>総予測需要量:</strong> ${totalPredicted}個</p>
      <p><strong>予測精度:</strong> 85.2%（平均）</p>
    `;

    // 在庫情報表示の更新
    const inventoryContent = container.querySelector("#inventory-content");
    const totalStock = results.reduce((sum, r) => sum + r.currentStock, 0);
    const needOrderCount = results.filter(r => r.orderQuantity > 0).length;
    inventoryContent.innerHTML = `
      <p><strong>総在庫数:</strong> ${totalStock}個</p>
      <p><strong>発注が必要な商品:</strong> ${needOrderCount}件</p>
      <p><strong>在庫回転率:</strong> 2.3回/月（平均）</p>
    `;
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 0;
    const reorderPoint = parseInt(container.querySelector("#reorder-point").value) || 0;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }

    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }

    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return false;
    }

    if (new Date(periodStart) > new Date(periodEnd)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }

    if (safetyStock < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }

    if (leadTime <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }

    if (reorderPoint < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return {
      storeId,
      category,
      periodStart,
      periodEnd,
      safetyStock,
      leadTime,
      reorderPoint
    };
  }

  // 計算実行
  async function executeCalculation() {
    const inputs = validateInputs();
    if (!inputs) return;

    // 需要予測データの取得
    if (!(await loadForecastData())) return;

    // 対象商品の絞り込み
    const targetProducts = productData.filter(p => {
      // カテゴリでフィルタ（簡易実装：商品名に含まれるかで判定）
      const categoryMatch = inputs.category === "食品" && (p.商品名.includes("食品") || p.商品名.includes("パン") || p.商品名.includes("米")) ||
                           inputs.category === "日用品" && (p.商品名.includes("日用品") || p.商品名.includes("洗剤") || p.商品名.includes("ティッシュ")) ||
                           inputs.category === "衣料品" && (p.商品名.includes("衣料") || p.商品名.includes("シャツ") || p.商品名.includes("服")) ||
                           inputs.category === "家電" && (p.商品名.includes("家電") || p.商品名.includes("電気")) ||
                           inputs.category === "書籍" && (p.商品名.includes("書籍") || p.商品名.includes("本"));

      return categoryMatch || Math.random() > 0.7; // デモ用：一部商品をランダムに含める
    });

    if (targetProducts.length === 0) {
      showError("選択された条件に該当する商品が見つかりません");
      return;
    }

    const results = [];

    for (const product of targetProducts.slice(0, 10)) { // 最大10件に制限
      // 需要予測データの取得
      const forecast = forecastData.find(f => 
        f.店舗ID === inputs.storeId && 
        f.商品ID === product.id &&
        f.予測対象日>= inputs.periodStart &&
        f.予測対象日<= inputs.periodEnd
      ) || { 予測数量: Math.floor(Math.random() * 100) + 10 }; // デモ用デフォルト値

      // 在庫データの取得
      const inventory = await getInventoryData(inputs.storeId, product.id);
      if (!inventory) continue;

      // 発注量計算
      const calculation = calculateOrderQuantity(
        forecast,
        inventory,
        inputs.safetyStock,
        inputs.leadTime,
        inputs.reorderPoint
      );

      results.push({
        id: `calc_${Date.now()}_${product.id}`,
        productId: product.id,
        productName: product.商品名,
        productCode: product.商品コード,
        predictedDemand: forecast.予測数量,
        currentStock: inventory.currentStock,
        safetyStock: inputs.safetyStock,
        reorderPoint: calculation.reorderPoint,
        orderQuantity: calculation.orderQuantity,
        orderTiming: calculation.orderTiming
      });
    }

    calculationResults = results;
    renderResults(results);
    showResultSections();
  }

  // 商品詳細表示
  function showProductDetail(productId) {
    // 商品詳細画面への遷移（実際の画面IDに置き換え）
    window.showScreen("scr-1778591945891"); // 在庫照会画面
  }

  // 初期化
  async function initialize() {
    await loadStoreData();
    await loadProductData();

    // デフォルト日付設定
    const today = new Date();
    const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
    container.querySelector("#period-start").value = today.toISOString().split('T')[0];
    container.querySelector("#period-end").value = nextWeek.toISOString().split('T')[0];
  }

  // イベントリスナー
  container.querySelector("#btn-calculate").addEventListener("click", executeCalculation);

  // 商品詳細リンクのイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const productLink = e.target.closest(".product-detail-link");

    if (detailBtn) {
      const productId = detailBtn.dataset.productId;
      showProductDetail(productId);
    } else if (productLink) {
      e.preventDefault();
      const productId = productLink.dataset.productId;
      showProductDetail(productId);
    }
  });

  // 初期化実行
  initialize();
}
